Usando refactor-modularize-code, quiero extraer la búsqueda de esta lista a un componente hijo `OperatorSearch`. El padre debe seguir deshabilitando el scanner mientras el foco está en la búsqueda y debe limpiar la búsqueda al agregar un operador. Código actual:

```tsx
export function OperatorList({ operators, onAddOperator }: OperatorListProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  useScanner({ enabled: !isSearchFocused, onScan: onAddOperator });
  const visibleOperators = operators.filter((operator) =>
    operator.name.toLowerCase().includes(searchTerm.toLowerCase()),
  );
  const handleAdd = (operator: Operator) => {
    onAddOperator(operator);
    setSearchTerm('');
  };
  return (
    <section>
      <input
        value={searchTerm}
        onChange={(event) => setSearchTerm(event.target.value)}
        onFocus={() => setIsSearchFocused(true)}
        onBlur={() => setIsSearchFocused(false)}
      />
      {visibleOperators.map((operator) => (
        <OperatorRow key={operator.id} operator={operator} onAdd={handleAdd} />
      ))}
    </section>
  );
}
```

